@import url(https://fonts.googleapis.com/css?family=PT+Sans:400,700&subset=cyrillic-ext,latin-ext);

/* modal */
#comebacker {
	background: url(img/bgexit.png);
    position: fixed;
    left: 0;
    top: 0; 
    z-index: 9999;
    width: 100%;
    height: 100%; 
	overflow: auto;
	display: none;
}   

#comebacker .close-undermodal {
	width: 100%;
	height: 100%;
	position: absolute;
	cursor: pointer;
}

#comebacker .close-over {
	background: url(img/close.png) no-repeat 0 0;
	width: 30px;
	height: 30px;
	position: absolute;
	right: 10px;
	top: 10px;
	cursor: pointer;
}

#comebacker .close-over:hover {
	background-position: 0 bottom;
} 

#comebacker .over-window {
	background: url(img/product.png) no-repeat 40px center #fff;
    cursor: default;
    left: 0;
	right: 0; 
	top: 10%;
    margin: 0 auto 20px auto;
    position: fixed;
	padding: 60px 20px 60px 20px;
    width: 560px;
    z-index: 9999;
	position: relative;
	font-family: 'PT Sans',arial,sans-serif !important;
} 

#comebacker .title-comebacker {
	font-size: 28px;
	font-weight: 700;
	color: #000;
	text-align: center;
	padding: 0 0 30px 0;
	margin: 0 0 0 50%;
}

#comebacker .title-oui div{
	font-size: 20px;
}

#comebacker .form {
	margin: 0 0 0 50%;
}

#comebacker .form form {
	margin: 0 !important;
}

#comebacker .form input[type="text"] {
	background: #fff;
	border: 1px solid #a5a5a5;
	outline: none;
	height: 45px;
	line-height: 45px;
	font-size: 18px;
	font-family: 'PT Sans',arial,sans-serif;
	width: 250px;
	box-sizing: border-box;
	border-radius: 0 !important;
	-moz-border-radius: 0 !important;
	padding: 0 20px;
	display: block;
	margin: 0 auto 20px auto;
}

#comebacker .form input[type="text"]:focus {
	border: 1px solid #054155;
}

#comebacker .form input[type="submit"] {
	background: #054155;
	cursor: pointer;
	border-radius: 5px;
	-moz-border-radius: 5px;
	outline: none;
	height: 50px;
	font-size: 24px;
	text-transform: uppercase;
	font-weight: 700;
	font-family: 'PT Sans',arial,sans-serif;
	width: 250px; 
	display: block;
	margin: 0 auto 0 auto;
	border: 0px;
	color: #ffffff;
}

#comebacker .form input[type="submit"]:hover {
	background: #10a9dc;
}

.comebackerhidden {
	overflow: hidden;
}

$(function() {
	$('.close-over, .close-undermodal').on('click', function () {
		$('#comebacker').fadeOut(300); // 300 скорость исчезновения | disappear speed
		$('body').removeClass('comebackerhidden');
	});

	var comebacker = true;
	
	$(window).mouseout(function(e){
		if(e.pageY - $(window).scrollTop() < 1 && comebacker == true){
			$('#comebacker').fadeIn(300); 
			$('body').addClass('comebackerhidden');
			comebacker = false;
		}
	});

	try {
		setTimeout(
			function show_comebacker() {
				$('#comebacker').fadeIn(300); // 300 скорость появления | appear speed 
				$('body').addClass('comebackerhidden');
			}, 3000 //Время появления в милисекундах | Appear time in milliseconds
		)
	}
	catch (e) {}
});

window.demoLog=function(value){let log=document.querySelector('#event-log');if(!log){log=document.createElement('output');log.id='event-log';log.setAttribute('aria-live','polite');(document.querySelector('main')||document.body).append(log);}log.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);};
window.addEventListener('error',event=>{if(event.message&&document.body)demoLog('Ошибка примера: '+event.message);});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='commentForm')return;if(!event.target.reportValidity())return;window.demoLog('Форма заполнена. Отправка отключена в примере.');});
document.addEventListener('DOMContentLoaded',()=>{
  addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='yellow-demo-height'||!Number.isFinite(event.data.height))return;const frame=[...document.querySelectorAll('iframe')].find(f=>f.contentWindow===event.source);if(frame)frame.style.height=Math.max(100,Math.min(4000,event.data.height))+'px';});
  const report=()=>{const main=document.querySelector('main')||document.body;const rect=main.getBoundingClientRect();const height=Math.ceil(rect.bottom+scrollY+24);if(parent!==window)parent.postMessage({type:'yellow-demo-height',height},location.origin);};
  new ResizeObserver(report).observe(document.querySelector('main')||document.body);
  new MutationObserver(report).observe(document.body,{subtree:true,childList:true});
  addEventListener('load',report);report();
});
